import {passwordPayload} from './state.js';
import {h} from 'preact';
import {useState} from 'preact/hooks';
import {Page,Field,Button,Notice,DataTable,ConfirmButton} from '../../components/ui.jsx';
import {usePaged,ListState,useAction,ActionNotice} from './forms.jsx';
export function AccountSecurity({api,store,navigate}) {
  const page=usePaged(api,'/auth/sessions');
  const action=useAction(()=>page.reload());
  const [values,setValues]=useState({currentPassword:'',password:'',confirm:''});
  const update=key=>e=>setValues({...values,[key]:e.target.value});
  async function change(event) {
    event.preventDefault();
    await action.run(signal=>api.post('/auth/password/change',passwordPayload(values,{changing:true}),{signal}),'Password changed. Other sessions and API tokens were revoked.',result=>{setValues({currentPassword:'',password:'',confirm:''});if(result.signInRequired){store.set({user:null});navigate('/login');}});
  }
  async function revoke(session) {
    await action.run(signal=>api.delete('/auth/sessions/'+session.id,undefined,{signal}),'Session revoked.',result=>{if(result.current){store.set({user:null});navigate('/login');}});
  }
  return <Page title="Account security"><ActionNotice action={action}/>
    <nav className="subnav"><a href="#/account/tokens">Personal API tokens</a><a href="#/account/outbox">Your outbox</a></nav>
    <h2>Active sessions</h2><p>Revocation takes effect on the next request. Expired sessions are omitted.</p>
    <ListState page={page}><DataTable items={page.items} empty="No active browser sessions." columns={[
      {key:'current',label:'Session',render:item=>item.current?'This browser':'Another browser'},
      {key:'userAgent',label:'Client'},{key:'lastUsedAt',label:'Last used'},{key:'expiresAt',label:'Expires'},
      {key:'revoke',label:'Action',render:item=><ConfirmButton busy={action.busy} message={item.current?'Sign out this browser?':'Revoke this session?'} onConfirm={()=>revoke(item)}>Revoke</ConfirmButton>}
    ]}/></ListState>
    <ConfirmButton busy={action.busy} message="Sign out all other browser sessions?" onConfirm={()=>action.run(signal=>api.post('/auth/sessions/revoke-others',{},{signal}),'Other sessions revoked.')}>Revoke all other sessions</ConfirmButton>
    <h2>Change password</h2><p>Your current browser stays signed in. Every other session and personal API token is revoked.</p>
    <form onSubmit={change}>
      <Field label="Current password" type="password" autoComplete="current-password" required value={values.currentPassword} onInput={update('currentPassword')} error={action.error?.details?.currentPassword}/>
      <Field label="New password" type="password" autoComplete="new-password" required minLength={10} maxLength={1024} value={values.password} onInput={update('password')} error={action.error?.details?.password}/>
      <Field label="Confirm new password" type="password" autoComplete="new-password" required value={values.confirm} onInput={update('confirm')} error={action.error?.details?.confirm}/>
      <Button busy={action.busy}>Change password</Button>
    </form><p><a href="#/reset">Request a password reset</a></p>
  </Page>;
}
export function ResetPassword({query,api,store,navigate}) {
  const token=query.token??'';
  const [values,setValues]=useState({email:'',password:'',confirm:''});
  const action=useAction(undefined,token);
  const update=key=>e=>setValues({...values,[key]:e.target.value});
  async function submit(event) {
    event.preventDefault();
    if(!token){await action.run(signal=>api.post('/auth/password/reset/request',{email:values.email},{signal}),'If this account exists, a reset link is now in its outbox.');return;}
    await action.run(signal=>api.post('/auth/password/reset',{token,...passwordPayload(values)},{signal}),'Password reset. Sign in with the new password.',()=>{store.set({user:null,notice:'Password reset. Sign in with your new password.'});navigate('/login');});
  }
  return <Page title={token?'Set a new password':'Request password reset'}><ActionNotice action={action}/>
    <p>{token?'This one-use link expires after one hour. Resetting revokes every session and API token.':'Enter your account email. This installation delivers links through its local outbox.'}</p>
    <form onSubmit={submit}>{token?<>
      <Field label="New password" type="password" autoComplete="new-password" required minLength={10} value={values.password} onInput={update('password')} error={action.error?.details?.password}/>
      <Field label="Confirm password" type="password" autoComplete="new-password" required value={values.confirm} onInput={update('confirm')} error={action.error?.details?.confirm}/>
    </>:<Field label="Account email" type="email" required value={values.email} onInput={update('email')} error={action.error?.details?.email}/>}
      <Button busy={action.busy}>{token?'Reset password':'Request reset link'}</Button>
    </form><p><a href="#/login">Return to sign in</a></p>
  </Page>;
}

import {h} from 'preact';
import {useState} from 'preact/hooks';
import {Page,Field,Button,Notice,DataTable,Loading,ConfirmButton,useLoad} from '../../components/ui.jsx';
import {OrganizationLinks} from './organizations.jsx';
import {roleOptions,canManage,organizationPath,invitationPayload} from './state.js';
import {usePaged,ListState,useAction,ActionNotice} from './forms.jsx';
export function Invitations({params,api}) {
  const id=params.orgId;
  const org=useLoad(()=>api.get('/orgs/'+id),[id]);
  const [state,setState]=useState('all');
  const page=usePaged(api,'/orgs/'+id+'/invitations?state='+state);
  const action=useAction(()=>page.reload(),id+':'+state);
  const [values,setValues]=useState({email:'',role:'member',expiresInHours:168,projects:''});
  const update=key=>event=>setValues({...values,[key]:event.target.value});
  async function create(event) {
    event.preventDefault();
    await action.run(signal=>api.post('/orgs/'+id+'/invitations',invitationPayload(values),{signal}),'Invitation created. The recipient link is in the local email outbox.',()=>setValues({...values,email:'',projects:''}));
  }
  const organization=org.data?.organization;
  return <Page title={(organization?.name??'Organization')+' · Invitations'}>
    <OrganizationLinks id={id}/><Notice error={org.error}/><ActionNotice action={action}/>
    {org.loading?<Loading/>:canManage(organization?.role)?<>
      <p>Invitations can be used once by an account with the exact invited email. Expired or revoked links grant no access.</p>
      <Field label="Show invitations"><select value={state} onChange={e=>setState(e.target.value)}>
        {['all','pending','accepted','revoked','expired'].map(value=><option value={value}>{value}</option>)}
      </select></Field>
      <ListState page={page}><DataTable items={page.items} empty="No invitations in this state." columns={[
        {key:'email',label:'Recipient'},{key:'role',label:'Role'},{key:'state',label:'State'},
        {key:'expiresAt',label:'Expires'},{key:'actions',label:'Actions',render:invite=>invite.state==='pending'&&
          <ConfirmButton busy={action.busy} message={'Revoke invitation for '+invite.email+'?'} onConfirm={()=>action.run(signal=>api.delete('/invitations/'+invite.id,undefined,{signal}),'Invitation revoked.')}>Revoke</ConfirmButton>}
      ]}/></ListState>
      <h2>Invite a colleague</h2><form onSubmit={create}>
        <Field label="Recipient email" type="email" required value={values.email} onInput={update('email')} error={action.error?.details?.email}/>
        <Field label="Organization role" error={action.error?.details?.role}><select value={values.role} onChange={update('role')}>{roleOptions(organization?.role).map(role=><option>{role}</option>)}</select></Field>
        <Field label="Expires in hours" type="number" min="1" max="720" value={values.expiresInHours} onInput={update('expiresInHours')} error={action.error?.details?.expiresInHours}/>
        {values.role==='guest'&&<Field label="Allowed project ids, separated by commas" value={values.projects} onInput={update('projects')} error={action.error?.details?.projectIds}/>}
        <Button busy={action.busy}>Create invitation</Button>
      </form><p><a href={'#/orgs/'+id+'/outbox'}>Open invitation outbox</a></p>
    </>:<p>Owners and administrators manage invitations.</p>}
  </Page>;
}
export function AcceptInvitation({query,user,api,navigate}) {
  const token=query.token??'';
  const preview=useLoad(()=>api.post('/invitations/preview',{token}),[token]);
  const action=useAction(result=>navigate(organizationPath(result.membership.orgId)),token);
  const invitation=preview.data?.invitation;
  return <Page title="Join an organization">
    <Notice error={preview.error}/><ActionNotice action={action}/>
    {preview.loading?<Loading/>:invitation&&<>
      <p><strong>{invitation.organizationName}</strong> invited <strong>{invitation.email}</strong> as {invitation.role}.</p>
      <p>This link expires {new Date(invitation.expiresAt).toLocaleString()}.</p>
      {!user?<p><a href="#/login">Sign in</a> or <a href="#/signup">create an account</a> with the invited address, then return to this invitation link.</p>:
        user.email.toLowerCase()!==invitation.email.toLowerCase()?<Notice error="This invitation belongs to a different email address. Sign out and use the invited account."/>:
          <Button busy={action.busy} onClick={()=>action.run(signal=>api.post('/invitations/accept',{token},{signal}),'Membership created.')}>Accept invitation</Button>}
    </>}
  </Page>;
}
export function Outbox({params,api}) {
  const orgId=params.orgId;
  const [kind,setKind]=useState('');
  const path=orgId?'/orgs/'+orgId+'/outbox':'/me/outbox'+(kind?'?kind='+kind:'');
  const page=usePaged(api,path);
  const [opened,setOpened]=useState(null);
  return <Page title={orgId?'Invitation outbox':'Your email outbox'}>
    {orgId&&<OrganizationLinks id={orgId}/>}
    <p>Local delivery replaces email in this installation. These messages contain private one-use links. Treat them as account credentials.</p>
    {!orgId&&<Field label="Message kind"><select value={kind} onChange={e=>setKind(e.target.value)}>{['','invite','reset','digest'].map(value=><option value={value}>{value||'All messages'}</option>)}</select></Field>}
    <ListState page={page}><DataTable items={page.items} columns={[
      {key:'toEmail',label:'To'},{key:'subject',label:'Subject'},{key:'createdAt',label:'Created'},
      {key:'open',label:'Message',render:item=><Button onClick={()=>setOpened(item)}>View message</Button>}
    ]} empty="No outbox messages."/></ListState>
    {opened&&<section aria-label="Outbox message"><h2>{opened.subject}</h2><p>{opened.toEmail}</p><p>{opened.textBody}</p>
      {opened.payload.link&&<p><a href={opened.payload.link}>Open one-use link</a></p>}
      <Button onClick={()=>setOpened(null)}>Close message</Button></section>}
  </Page>;
}

import {useState} from 'preact/hooks';
import {Page,Field,Button,Notice,DataTable,ConfirmButton,Loading} from '../../components/ui.jsx';
import {queryString} from '../../api.js';
import {useScopedLoad} from '../insight/scoped-load.js';
import {OrganizationLinks} from './organizations.jsx';
import {useAction,ActionNotice,usePaged,ListState} from './forms.jsx';
function capabilities(permissions){return permissions.length?permissions.join(', '):'No capabilities';}
export function MemberAccess({params,api}) {
  const {orgId,userId}=params,base='/orgs/'+orgId+'/members/'+userId;
  const scope=JSON.stringify([orgId,userId]);
  const detail=useScopedLoad(scope,()=>api.get(base+'/access'),[scope]);
  const [draft,setDraft]=useState(''),[query,setQuery]=useState(''),[mode,setMode]=useState('all');
  const [choice,setChoice]=useState(null),[review,setReview]=useState(null);
  const path=base+'/projects?'+queryString({q:query,mode});
  const page=usePaged(api,path,20);
  const access=detail.data,member=access?.membership;
  const action=useAction(()=>{detail.reload();page.reload();},JSON.stringify([scope,path]));
  const proposal=choice?.scope===scope?choice.role:member?.role;
  const reviewed=review?.scope===scope&&review.membership.revision===member?.revision?review:null;
  async function changeRole() {
    if(!reviewed)return;
    await action.run(async signal=>{
      const latest=await api.get(base+'/access',{signal});
      if(JSON.stringify(latest)!==JSON.stringify(reviewed.access))throw new Error('Access changed after this preview. Refresh and review the role again.');
      return api.patch(base,{role:reviewed.role,expectedRevision:reviewed.membership.revision},{signal});
    },'Role updated.',()=>{setReview(null);setChoice(null);});
  }
  return <Page title={member?member.name+' · Member access':'Member access'}>
    <OrganizationLinks id={orgId}/><p><a href={'#/orgs/'+orgId+'/members'}>Back to members</a></p>
    <Notice error={detail.error}/><ActionNotice action={action}/>
    <p>Direct grants are stored independently of role access. Leaving a guest role retains its grants; returning to guest makes those retained grants effective again. Abandoning a local request does not undo an accepted server change.</p>
    <Button type="button" disabled={action.busy} onClick={()=>{setReview(null);detail.reload();page.reload();}}>Refresh member access</Button>
    {detail.loading?<Loading/>:member&&<>
      <p>Current role: <strong>{member.role}</strong>. {access.counts.total} projects, including {access.counts.archived} archived. Direct grants: {access.counts.direct}; {member.role==='guest'?'effective grants':'dormant grants; role access covers all projects'}.</p>
      {access.lastOwner&&<Notice>This is the last owner. Add another owner before downgrading or removing this membership.</Notice>}
      <h2>Review a role change</h2><p>Choosing a role changes this preview only. Confirming is a separate action.</p>
      <Field label="Proposed role"><select disabled={action.busy||!access.canChangeRole} value={proposal} onChange={e=>{setChoice({scope,role:e.target.value});setReview(null);}}>
        {access.roles.map(item=><option value={item.role} disabled={!item.selectable}>{item.role}</option>)}
      </select></Field>
      <Button type="button" disabled={action.busy||proposal===member.role||!access.roles.find(item=>item.role===proposal)?.selectable} onClick={()=>setReview({scope,role:proposal,membership:member,access})}>Review role change</Button>
      {reviewed&&<section aria-label="Role change impact"><h3>{member.name}: {member.role} → {reviewed.role}</h3>
        <DataTable items={[{id:'before',label:'Before',...access.roles.find(item=>item.role===member.role)},{id:'after',label:'After confirmation',...access.roles.find(item=>item.role===reviewed.role)}]} columns={[
          {key:'label',label:'Decision'},{key:'role',label:'Role'},{key:'effectiveProjects',label:'Projects accessible'},
          {key:'dormantGrants',label:'Dormant direct grants'},{key:'permissions',label:'Capabilities',render:item=>capabilities(item.permissions)}]}/>
        <p>Direct grants remain {access.counts.direct}. {reviewed.role==='guest'?`${access.counts.total-access.counts.direct} projects lose role-derived access. Only the direct grants listed below remain available.`:'Organization role grants access to every current project. Existing direct grants become dormant.'}</p>
        <Button type="button" busy={action.busy} onClick={changeRole}>Confirm role change</Button>
        <Button type="button" disabled={action.busy} onClick={()=>setReview(null)}>Cancel role change</Button>
      </section>}
      <h2>Direct project grants</h2>
      {member.role!=='guest'&&<Notice>New direct grants may be added only to a guest. Removing a dormant grant leaves current role access intact and affects a future downgrade.</Notice>}
      <form onSubmit={e=>{e.preventDefault();setQuery(draft);}}>
        <Field label="Search projects" type="search" value={draft} onInput={e=>setDraft(e.target.value)}/><Button>Search projects</Button>
      </form>
      <Field label="Project access view"><select value={mode} onChange={e=>setMode(e.target.value)}><option value="all">All manageable projects</option><option value="direct">Recorded direct grants</option></select></Field>
      <p>{page.data?.total??0} matching projects. Current page keeps full project names beside every decision.</p>
      <ListState page={page}><DataTable items={page.items} empty="No projects match this access view." columns={[
        {key:'name',label:'Project',render:project=><span>{project.key} · {project.name}{project.archived?' (archived)':''}</span>},
        {key:'effective',label:'Effective access',render:project=>project.effective?member.role==='guest'?'Direct grant':'Organization role':'No access'},
        {key:'direct',label:'Direct grant',render:project=>project.direct?project.dormant?'Recorded, dormant':'Recorded, effective':'None'},
        {key:'decision',label:'Explicit decision',render:project=>project.direct?<ConfirmButton busy={action.busy} message={'Remove the direct grant for '+member.name+' on '+project.key+' · '+project.name+'? '+(member.role==='guest'?'Project access will be lost.':'Current role access will remain.')} onConfirm={()=>action.run(signal=>api.delete('/projects/'+project.id+'/guests/'+userId,undefined,{signal}),'Direct grant removed.',()=>setReview(null))}>Remove direct grant</ConfirmButton>:<ConfirmButton busy={action.busy} disabled={member.role!=='guest'} message={'Grant '+member.name+' access to '+project.key+' · '+project.name+(project.archived?' (archived, read-only)':'')+'?'} onConfirm={()=>action.run(signal=>api.post('/projects/'+project.id+'/guests',{userId},{signal}),'Direct grant added.',()=>setReview(null))}>Add direct grant</ConfirmButton>}
      ]}/></ListState>
    </>}
    {detail.error&&<p>Current access could not be established. Role and grant controls are unavailable; refresh after resolving access.</p>}
  </Page>;
}

import {MemberAccess} from './member-access.jsx';
import {PersonalTokens} from './tokens.jsx';
import {SecurityAudit} from './audit.jsx';
import {Invitations,AcceptInvitation,Outbox} from './invitations.jsx';
import {AccountSecurity,ResetPassword} from './account.jsx';
import {Organizations,Members,Teams,TeamDetail} from './organizations.jsx';
export const routes=[{path:'/orgs/:orgId/members/:userId/access',component:MemberAccess},{path:'/account/tokens',component:PersonalTokens},{path:'/account/audit',component:SecurityAudit},{path:'/orgs/:orgId/audit',component:SecurityAudit},{path:'/orgs/:orgId/invitations',component:Invitations},{path:'/orgs/:orgId/outbox',component:Outbox},{path:'/invitations/accept',component:AcceptInvitation},{path:'/account/security',component:AccountSecurity},{path:'/account/outbox',component:Outbox},{path:'/reset',component:ResetPassword},{path:'/orgs',component:Organizations},{path:'/orgs/:orgId/members',component:Members},{path:'/orgs/:orgId/teams',component:Teams},{path:'/teams/:teamId',component:TeamDetail}];
export const navigation=[{path:'/orgs',label:'Organizations'},{path:'/account/security',label:'Account security'}];

import {h} from 'preact';
import {useState} from 'preact/hooks';
import {PERMISSIONS} from '@crew/shared';
import {Page,Field,Button,Notice,DataTable,ConfirmButton} from '../../components/ui.jsx';
import {usePaged,ListState,useAction,ActionNotice} from './forms.jsx';
import {tokenPayload} from './state.js';
export function PersonalTokens({api}) {
  const [filter,setFilter]=useState('all');
  const page=usePaged(api,'/tokens?state='+filter);
  const [values,setValues]=useState({name:'',scopes:['self:read','org:read','project:read','insight:read'],expiresInDays:'30'});
  const [secret,setSecret]=useState(null);
  const action=useAction(()=>{page.reset();page.reload();},filter);
  async function create(event) {
    event.preventDefault();
    await action.run(signal=>api.post('/tokens',tokenPayload(values),{signal}),'Token created. Copy its credential now.',result=>{setSecret(result.token);setValues({...values,name:''});});
  }
  function toggle(scope) {setValues({...values,scopes:values.scopes.includes(scope)?values.scopes.filter(item=>item!==scope):[...values.scopes,scope]});}
  return <Page title="Personal API tokens">
    <nav className="subnav"><a href="#/account/security">Account security</a><a href="#/account/audit">Your security audit</a></nav>
    <p>Use tokens with the CLI. Scopes limit API operations; your role and project grants still apply. Revocation is immediate.</p>
    <ActionNotice action={action}/>
    {secret&&<section aria-label="New API credential"><h2>Copy your token</h2><Notice>This credential is displayed once. Store it privately before leaving this page.</Notice>
      <Field label="New token credential"><textarea readOnly value={secret} onFocus={e=>e.target.select()}/></Field>
      <Button onClick={()=>setSecret(null)}>I have saved it; hide token</Button>
    </section>}
    <Field label="Token state"><select value={filter} onChange={e=>setFilter(e.target.value)}>{['all','active','expired','revoked'].map(value=><option>{value}</option>)}</select></Field>
    <ListState page={page}><DataTable items={page.items} empty="No personal API tokens." columns={[
      {key:'name',label:'Name'},{key:'scopes',label:'Scopes',render:item=>item.scopes.join(', ')},{key:'state',label:'State'},
      {key:'expiresAt',label:'Expires',render:item=>item.expiresAt??'No expiry'},{key:'lastUsedAt',label:'Last used'},
      {key:'revoke',label:'Action',render:item=>item.state!=='revoked'&&<ConfirmButton busy={action.busy} message={'Revoke token '+item.name+'? Applications using it will stop authenticating.'}
        onConfirm={()=>action.run(signal=>api.delete('/tokens/'+item.id,undefined,{signal}),'Token revoked.')}>Revoke</ConfirmButton>}
    ]}/></ListState>
    <h2>Create personal token</h2><form onSubmit={create}>
      <Field label="Token name" required maxLength={100} value={values.name} onInput={e=>setValues({...values,name:e.target.value})} error={action.error?.details?.name}/>
      <Field label="Expires in days; leave blank for no expiry" type="number" min="1" max="365" value={values.expiresInDays} onInput={e=>setValues({...values,expiresInDays:e.target.value})} error={action.error?.details?.expiresInDays}/>
      <fieldset><legend>Allowed operations</legend><p>Choose the smallest set needed. A global wildcard authorizes every operation your account may perform.</p>
        {['*',...PERMISSIONS].map(scope=><label className="field"><span><input type="checkbox" checked={values.scopes.includes(scope)} onChange={()=>toggle(scope)}/> {scope}</span></label>)}
        {action.error?.details?.scopes&&<Notice error={action.error.details.scopes}/>}
      </fieldset><Button busy={action.busy}>Create token</Button>
    </form>
  </Page>;
}
